{
  "sub_hypo": [
    {
      "text": "Higher time preference is associated with higher BMI for 1989 data.",
      "context": "Participants in the National Longitudinal Survey of Youth (NLSY79), using 1989 data and height measured in 1985.",
      "variables": [
        "Was more money put into or taken out of R/spouse savings since last interview, 1989: time preference proxy encoded as DISSAVED = 1 for 'TOOK MORE MONEY OUT', otherwise 0; SAMESAVE = 1 for 'NO SAVINGS' or 'NO CHANGE', otherwise 0",
        "BMI, derived from Weight of respondent, 1989 and Height of respondent, 1985"
      ],
      "relations": "Positive association between time preference and BMI, evaluated using OLS regression with DISSAVED and SAMESAVE as independent variables and BMI as the dependent variable."
    }
  ]
}

{
  "sub_hypo": [
    {
      "text": "Higher time preference, measured by dissaving in 1989, is associated with modestly higher BMI in 1989.",
      "context": "NLSY79 observational data; BMI restricted to 15–60. HC1-robust OLS adjusted for sex, racial/ethnic cohort, age, family size, parental and own education, ASVAB, log 1979 income, and ever-institutionalized status. Savings-direction complete-case n=6,295.",
      "variables": [
        "Was more money put into or taken out of R/spouse savings since last interview, 1989",
        "Weight of respondent, 1989",
        "Height of respondent, 1985"
      ],
      "relations": "Dissavers have approximately 0.26 higher BMI units. With 'no savings' modeled separately, dissavers have 0.45 higher BMI units than savers, and the 'no savings' group has 0.54 higher BMI units. These are modest observational associations; causality is not established and reverse causality is plausible."
    },
    {
      "text": "Higher net savings flow in 1989 is associated with lower BMI in 1989.",
      "context": "NLSY79; adjusted HC1-robust OLS using winsorized/quintiled net savings flow and BMI restricted to 15–60; complete-case n=3,481. Adjustment includes sex, racial/ethnic cohort, age, family size, parental and own education, ASVAB, log 1979 income, and ever-institutionalized status.",
      "variables": [
        "Net amount respondent/spouse put into savings since last interview, 1989",
        "Net amount respondent/spouse took out of savings since last interview, 1989",
        "Weight of respondent, 1989",
        "Height of respondent, 1985"
      ],
      "relations": "Each quintile increase toward higher net saving is associated with 0.19 fewer BMI units."
    },
    {
      "text": "Dissaving in 1989 predicts greater BMI gain between 1981 and 1989.",
      "context": "NLSY79; adjusted HC1-robust OLS of BMI change, with plausible BMI restricted to 15–60. Adjustment includes sex, racial/ethnic cohort, age, family size, parental and own education, ASVAB, log 1979 income, and ever-institutionalized status.",
      "variables": [
        "Was more money put into or taken out of R/spouse savings since last interview, 1989",
        "Weight of respondent, 1981",
        "Weight of respondent, 1989",
        "Height of respondent, 1981",
        "Height of respondent, 1985"
      ],
      "relations": "Dissaving is associated with 0.20 additional BMI units of gain from 1981 to 1989 (p=0.028), without establishing causality."
    },
    {
      "text": "Dissaving is associated with modestly higher odds of obesity.",
      "context": "NLSY79; obesity logistic regression adjusted for sex, racial/ethnic cohort, age, family size, parental and own education, ASVAB, log 1979 income, and ever-institutionalized status.",
      "variables": [
        "Was more money put into or taken out of R/spouse savings since last interview, 1989",
        "Weight of respondent, 1989",
        "Height of respondent, 1985"
      ],
      "relations": "The obesity odds ratio for dissaving is 1.17 (p=0.058)."
    },
    {
      "text": "Wealth accumulation between 1985 and 1990 shows no association with BMI in 1989.",
      "context": "NLSY79; sign-log wealth growth analyzed using adjusted HC1-robust OLS; complete-case n=5,244. Adjustment includes sex, racial/ethnic cohort, age, family size, parental and own education, ASVAB, log 1979 income, and ever-institutionalized status.",
      "variables": [
        "Family net wealth, 1985",
        "Family net wealth, 1990",
        "Weight of respondent, 1989",
        "Height of respondent, 1985"
      ],
      "relations": "No association is detected between wealth growth from 1985 to 1990 and BMI (p=0.71)."
    },
    {
      "text": "Higher wealth level in 1996 is weakly associated with lower BMI in 1989.",
      "context": "NLSY79; adjusted HC1-robust OLS; complete-case n=4,245. Adjustment includes sex, racial/ethnic cohort, age, family size, parental and own education, ASVAB, log 1979 income, and ever-institutionalized status.",
      "variables": [
        "Family net wealth, 1996 (key data point)",
        "Weight of respondent, 1989",
        "Height of respondent, 1985"
      ],
      "relations": "The 1996 wealth-level coefficient is weakly negative (-0.030, p=0.021); this association does not establish a causal protective effect."
    },
    {
      "text": "Contemporaneous income accounts for part of the association between dissaving and BMI.",
      "context": "NLSY79; sensitivity analysis adding 1989 income to the adjusted BMI model as a collider check.",
      "variables": [
        "Was more money put into or taken out of R/spouse savings since last interview, 1989",
        "Total net family income, previous calendar year, 1989",
        "Weight of respondent, 1989",
        "Height of respondent, 1985"
      ],
      "relations": "With contemporaneous income included, the dissaving coefficient attenuates to +0.17 BMI units (p=0.23)."
    }
  ]
}
